const PRODUCTS = [{"id":"service-apron","cat":"SERVICE","title":"Signature Service Apron","sub":"HORENOVA STUDIO · Concept","img":"https://static.wixstatic.com/media/d0158d_f0de10ebdb1b4f9db01bdcb5b3562dda~mv2.png","desc":"Tablier de service noir et chemise blanche · Prévisualisation conceptuelle"},{"id":"barista-apron","cat":"BARISTA","title":"Signature Barista Apron","sub":"HORENOVA STUDIO · Concept","img":"https://static.wixstatic.com/media/d0158d_d7684c61777049bca3320eb6588c452c~mv2.png","desc":"Tablier barista avec bretelles et serviette · Prévisualisation conceptuelle"},{"id":"chef-jacket","cat":"CHEF","title":"Executive Chef Jacket","sub":"HORENOVA STUDIO · Concept","img":"https://static.wixstatic.com/media/d0158d_a57fd1bc0b42499580dcf9669520c65d~mv2.png","desc":"Veste de chef croisée blanche · Prévisualisation conceptuelle"},{"id":"service-vest","cat":"SERVICE","title":"Service Vest","sub":"HORENOVA STUDIO · Concept","img":"https://static.wixstatic.com/media/d0158d_078d4431c60a4ce89aeca764edcb176e~mv2.png","desc":"Gilet de service noir sur chemise · Prévisualisation conceptuelle"},{"id":"housekeeping-tunic","cat":"ÉTAGE","title":"Housekeeping Tunic","sub":"HORENOVA STUDIO · Concept","img":"https://static.wixstatic.com/media/d0158d_705b282295e84c89bf7c530bf67a4bc1~mv2.png","desc":"Tunique d'étage grise · Prévisualisation conceptuelle"},{"id":"reception-blazer","cat":"ACCUEIL","title":"Reception Blazer","sub":"HORENOVA STUDIO · Concept","img":"https://static.wixstatic.com/media/d0158d_00a5e380f3c240ebbb411a0585e262bc~mv2.png","desc":"Veste de réception sombre · Prévisualisation conceptuelle"},{"id":"hotel-polo","cat":"ACCUEIL","title":"Hospitality Polo","sub":"HORENOVA STUDIO · Concept","img":"https://static.wixstatic.com/media/d0158d_7d8857fd321548cdb069c428da8feb24~mv2.png","desc":"Polo de service ivoire · Prévisualisation conceptuelle"}];

const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const KEY='horenova-shop-saved-v1';
let sessionSaved=null;
const saved=()=>{if(sessionSaved)return [...sessionSaved];try{const data=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(data)?[...new Set(data.filter(id=>typeof id==='string'&&PRODUCTS.some(p=>p.id===id)))]:[]}catch{return[]}};
const saveList=a=>{sessionSaved=[...a];try{localStorage.setItem(KEY,JSON.stringify(a))}catch{/* Keep the selection usable when storage is disabled. */}};
function toast(msg){let t=$('.shop17-toast');if(!t){t=document.createElement('div');t.className='shop17-toast';document.body.append(t)}t.textContent=msg;t.classList.add('show');clearTimeout(window.__shop17);window.__shop17=setTimeout(()=>t.classList.remove('show'),1700)}
function toggleSaved(id){let a=saved();a=a.includes(id)?a.filter(x=>x!==id):[...a,id];saveList(a);updateSaved();toast(a.includes(id)?'Ajouté à votre sélection':'Retiré de votre sélection')}
function updateSaved(){const n=saved().length;$$('[data-shop-saved-count]').forEach(x=>x.textContent=n);$$('[data-save-product]').forEach(b=>b.classList.toggle('saved',saved().includes(b.dataset.saveProduct)))}
function productCard(p){return `<article class="shop17-product" data-cat="${p.cat}"><a class="shop17-product-media" href="#hx-showroom" data-hx-select="${p.id}"><img src="${p.img}" alt="${p.title}" loading="lazy" decoding="async"><span>VIEW</span></a><div class="shop17-product-meta"><div><small>${p.cat}</small><h3>${p.title}</h3><p>${p.sub}</p></div><button type="button" aria-label="Ajouter à ma sélection" data-save-product="${p.id}">♡</button></div></article>`}
function renderShop(){const grid=$('#shop17Grid');if(!grid)return;grid.innerHTML=PRODUCTS.map(productCard).join('');grid.querySelectorAll('[data-hx-select]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();if(window.HORENOVA_SHOWROOM)window.HORENOVA_SHOWROOM.open(a.dataset.hxSelect);else location.href='/shop-product.html?id='+encodeURIComponent(a.dataset.hxSelect)}));updateSaved();$$('[data-save-product]').forEach(b=>b.onclick=()=>toggleSaved(b.dataset.saveProduct));$$('[data-shop-filter]').forEach(b=>b.onclick=()=>{const c=b.dataset.shopFilter;$$('[data-shop-filter]').forEach(x=>x.classList.toggle('active',x===b));$$('.shop17-product').forEach(card=>card.hidden=c!=='ALL'&&card.dataset.cat!==c)});}
function renderDetail(){const root=$('#shop17ProductDetail');if(!root)return;const id=new URLSearchParams(location.search).get('id');const p=PRODUCTS.find(x=>x.id===id);if(!p){root.innerHTML='<div class="empty-state"><h2>Produit introuvable.</h2><p>Ce produit n’est pas disponible dans notre catalogue.</p><a class="soft-btn" href="/shop.html">Revenir à la boutique ↗</a></div>';return;}document.title=`Horenova Shop — ${p.title}`;root.innerHTML=`<section class="shop17-detail"><div class="shop17-detail-media"><img src="${p.img}" alt="${p.title}"></div><div class="shop17-detail-copy"><a class="shop17-back" href="/shop.html">← SHOP</a><small>${p.cat}</small><h1>${p.title}</h1><p class="shop17-sub">${p.sub}</p><p>${p.desc}</p><div class="shop17-price-note">TAILLES & COLORIS</div><label class="shop18-variant-label">Taille<select id="shop18Size"><option>XS</option><option selected>M</option><option>L</option><option>XL</option><option>XXL</option></select></label><label class="shop18-variant-label">Couleur<select id="shop18Color"><option>Noir</option><option>Blanc</option><option>Olive</option><option>Beige</option></select></label><button class="shop17-detail-cta" type="button" data-save-product="${p.id}">Ajouter à ma sélection</button><div class="shop17-detail-lines"><span>Disponibilité à l’ouverture du Shop</span><span>Sélection métier Horenova</span><span>Fournisseurs à valider avant lancement</span></div></div></section><section class="shop17-related"><small>MORE FROM HORENOVA SHOP</small><div class="shop17-grid">${PRODUCTS.filter(x=>x.id!==p.id).slice(0,4).map(productCard).join('')}</div></section>`;updateSaved();$$('[data-save-product]').forEach(b=>b.onclick=()=>toggleSaved(b.dataset.saveProduct));}
function motion(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('show');io.unobserve(e.target)}}),{threshold:.08});$$('[data-shop17-reveal]').forEach(x=>io.observe(x))}
renderShop();renderDetail();motion();

/* SHOP THEATRE V18 */
function shopTheatre(){const e=document.getElementById('shop17Entrance'),btn=document.getElementById('shop17Enter'),main=document.getElementById('shop17Main');if(!e||!btn||!main)return;let entered=false;const open=()=>{if(entered)return;entered=true;e.classList.add('entering');btn.disabled=true;setTimeout(()=>{e.classList.add('entered');main.classList.add('shop17-revealed');main.removeAttribute('aria-hidden');window.scrollTo({top:0,behavior:'smooth'});},1300)};btn.addEventListener('click',open);const io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add('show');io.unobserve(x.target)}}),{threshold:.12});document.querySelectorAll('.shop17-product,.shop17-lookbook-grid figure,.shop17-editorial').forEach(x=>io.observe(x));}shopTheatre();
